import{_ as e,o as a,c as s,l as o,t as i,N as n}from"./chunks/framework.Bbd9fWQx.js";const y=JSON.parse('{"title":"git-request-pull | x-cmd man (git man1) | Generates a summary of pending changes","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-request-pull - Generates a summary of pending changes","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-request-pull | x-cmd man (git man1) | Generates a summary of pending changes"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-request-pull - Generates a summary of pending changes"}]]},"headers":[],"params":{"isMan":true,"man":"git-request-pull","category":"git man1","desc":"Generates a summary of pending changes"},"relativePath":"git/man1/git-request-pull.md","filePath":"git/man1/git-request-pull.md"}'),r={name:"git/man1/git-request-pull.md"},l={class:"visually-hidden"},p=n(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-request-pull - Generates a summary of pending changes</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> request-pull</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-p] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">start</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">end</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Generate a request asking your upstream project to pull changes into their tree. The request, printed to the standard output, begins with the branch description, summarizes the changes and indicates from where they can be pulled.</p><p>The upstream project is expected to have the commit named by <strong>&lt;start&gt;</strong> and the output asks it to integrate the changes you made since that commit, up to the commit named by <strong>&lt;end&gt;</strong>, by visiting the repository named by <strong>&lt;URL&gt;</strong>.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-p</p><blockquote><p>Include patch text in the output.</p></blockquote><p>&lt;start&gt;</p><blockquote><p>Commit to start at. This names a commit that is already in the upstream history.</p></blockquote><p>&lt;URL&gt;</p><blockquote><p>The repository URL to be pulled from.</p></blockquote><p>&lt;end&gt;</p><blockquote><p>Commit to end at (defaults to HEAD). This names the commit at the tip of the history you are asking to be pulled.</p><p>When the repository named by <strong>&lt;URL&gt;</strong> has the commit at a tip of a ref that is different from the ref you have locally, you can use the <strong>&lt;local&gt;:&lt;remote&gt;</strong> syntax, to have its local name, a colon <strong>:</strong>, and its remote name.</p></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>Imagine that you built your work on your <strong>master</strong> branch on top of the <strong>v1.0</strong> release, and want it to be integrated to the project. First you push that change to your public repository for others to see:</p><blockquote><pre><code>git push https://git.ko.xz/project master
</code></pre></blockquote><p>Then, you run this command:</p><blockquote><pre><code>git request-pull v1.0 https://git.ko.xz/project master
</code></pre></blockquote><p>which will produce a request to the upstream, summarizing the changes between the <strong>v1.0</strong> release and your <strong>master</strong>, to pull it from your public repository.</p><p>If you pushed your change to a branch whose name is different from the one you have locally, e.g.</p><blockquote><pre><code>git push https://git.ko.xz/project master:for-linus
</code></pre></blockquote><p>then you can ask that to be pulled with</p><blockquote><pre><code>git request-pull v1.0 https://git.ko.xz/project master:for-linus
</code></pre></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,28);function h(t,u,c,g,d,m){return a(),s("div",null,[o("h1",l,i(t.$params.man),1),p])}const b=e(r,[["render",h]]);export{y as __pageData,b as default};
